export function isOrdinaryLocalTest(problem: PublicProblemContent): boolean {
  const runtime = problem.judge_runtime;
  return !problem.interaction && !problem.local_judging
    && (!runtime || (runtime.execution_mode === 'batch' && runtime.build_mode === 'standalone' && runtime.evaluation_mode === 'tokens'))
    && ['default', 'tokens', 'token', ''].includes(problem.checker_type);
}

